package com.universidad.consultasmedicas.controller;
import com.universidad.consultasmedicas.dto.*; import com.universidad.consultasmedicas.service.GestionService;
import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class PageController {
 private final GestionService s; public PageController(GestionService s){this.s=s;}
 @GetMapping("/") public String root(){return "redirect:/login";}
 @GetMapping("/login") public String login(){return "login";} @GetMapping("/access-denied") public String denied(){return "403";}
 @GetMapping("/admin/dashboard") public String admin(Model m){m.addAttribute("medicos",s.medicos());m.addAttribute("pacientes",s.pacientes());m.addAttribute("consultas",s.consultas());m.addAttribute("totalMedicos",s.totalMedicos());m.addAttribute("totalConsultas",s.totalConsultas());return "admin";}
 @GetMapping("/admin/consultas/{id}/editar") public String editarForm(@PathVariable Long id,Model m){m.addAttribute("consulta",s.consulta(id));m.addAttribute("medicos",s.medicos());m.addAttribute("pacientes",s.pacientes());return "consulta-edit";}
 @PostMapping("/admin/medicos") public String crearMedico(@Valid @ModelAttribute MedicoRequest d,BindingResult b,RedirectAttributes ra){if(b.hasErrors()){ra.addFlashAttribute("error","Revise los datos del médico. La cuenta requiere contraseña de 8 caracteres.");return "redirect:/admin/dashboard";}s.crearMedico(d);ra.addFlashAttribute("success","Médico creado.");return "redirect:/admin/dashboard";}
 @PostMapping("/admin/medicos/{id}/editar") public String editarMedico(@PathVariable Long id,@RequestParam String nombre,@RequestParam String especialidad,@RequestParam(required=false) String telefono,RedirectAttributes ra){s.editarMedico(id,new MedicoUpdateRequest(nombre,especialidad,telefono));ra.addFlashAttribute("success","Médico actualizado.");return "redirect:/admin/dashboard";}
 @PostMapping("/admin/medicos/{id}/eliminar") public String eliminarMedico(@PathVariable Long id,RedirectAttributes ra){s.borrarMedico(id);ra.addFlashAttribute("success","Médico eliminado.");return "redirect:/admin/dashboard";}
 @PostMapping("/admin/pacientes") public String crearPaciente(@RequestParam String nombre,@RequestParam String username,@RequestParam String password,RedirectAttributes ra){if(nombre.isBlank()||nombre.length()>40||!nombre.matches("[\\p{L}\\p{N} .'-]+")||password.length()<8||username.isBlank()||username.length()>50)throw new IllegalArgumentException("Nombre alfanumérico (máx. 40), usuario y contraseña (mín. 8) requeridos");s.crearPaciente(nombre,username,password);ra.addFlashAttribute("success","Paciente y cuenta creados.");return "redirect:/admin/dashboard";}
 @PostMapping("/admin/consultas") public String crearConsulta(@Valid @ModelAttribute ConsultaRequest d,BindingResult b,RedirectAttributes ra){if(b.hasErrors()||!d.horarioValido()){ra.addFlashAttribute("error","Datos inválidos: verifique campos y horario.");return "redirect:/admin/dashboard";}s.crearConsulta(d);ra.addFlashAttribute("success","Consulta registrada.");return "redirect:/admin/dashboard";}
 @PostMapping("/admin/consultas/{id}/editar") public String editarConsulta(@PathVariable Long id,@Valid @ModelAttribute ConsultaRequest d,BindingResult b,RedirectAttributes ra){if(b.hasErrors()||!d.horarioValido()){ra.addFlashAttribute("error","Datos inválidos: verifique campos y horario.");return "redirect:/admin/dashboard";}s.editarConsulta(id,d);ra.addFlashAttribute("success","Consulta actualizada.");return "redirect:/admin/dashboard";}
 @PostMapping("/admin/consultas/{id}/eliminar") public String eliminarConsulta(@PathVariable Long id,RedirectAttributes ra){s.borrarConsulta(id);ra.addFlashAttribute("success","Consulta eliminada.");return "redirect:/admin/dashboard";}
 @GetMapping("/medico/dashboard") public String medico(Authentication a,Model m){var d=s.medicoActual(a.getName());m.addAttribute("medico",d);m.addAttribute("consultas",s.consultasMedico(a.getName()));return "medico";}
 @GetMapping("/paciente/dashboard") public String paciente(Authentication a,Model m){m.addAttribute("paciente",s.pacienteActual(a.getName()));m.addAttribute("consultas",s.consultasPaciente(a.getName()));return "paciente";}
 @PostMapping("/paciente/consultas/{id}/horario") public String actualizar(@PathVariable Long id,@RequestParam java.time.LocalTime horaInicio,@RequestParam java.time.LocalTime horaFin,Authentication a,RedirectAttributes ra){s.actualizarHorario(id,a.getName(),new HorarioRequest(horaInicio,horaFin));ra.addFlashAttribute("success","Horario actualizado.");return "redirect:/paciente/dashboard";}
}
